import { MakeLogicType, actions, connect, kea, listeners, path, selectors } from 'kea'
import { subscriptions } from 'kea-subscriptions'

import api from 'lib/api'
import { objectsEqual } from 'lib/utils/objects'

import { HogFlow } from './hogflows/types'
import { syncWaitingStatusCheck } from './waitingStatusCheck'
import { WorkflowsListParams, WorkflowsResult, workflowsLogic } from './workflowsLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workflowsWaitingRefreshLogicValues {
    paramsFromFilters: WorkflowsListParams // workflowsLogic
    workflows: WorkflowsResult // workflowsLogic
    workflowsLoading: boolean // workflowsLogic
    hasWaitingWorkflows: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workflowsWaitingRefreshLogicActions {
    loadWorkflowsSuccess: (
        workflows: WorkflowsResult,
        payload?: {}
    ) => {
        workflows: WorkflowsResult
        payload?: {}
    } // workflowsLogic
    refreshWaitingWorkflows: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workflowsWaitingRefreshLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        hasWaitingWorkflows: (workflows: WorkflowsResult) => boolean
    }
}

export type workflowsWaitingRefreshLogicType = MakeLogicType<
    workflowsWaitingRefreshLogicValues,
    workflowsWaitingRefreshLogicActions,
    {},
    workflowsWaitingRefreshLogicMeta
>

export const workflowsWaitingRefreshLogic = kea<workflowsWaitingRefreshLogicType>([
    path(['products', 'workflows', 'frontend', 'workflowsWaitingRefreshLogic']),
    connect(() => ({
        values: [workflowsLogic, ['paramsFromFilters', 'workflows', 'workflowsLoading']],
        actions: [workflowsLogic, ['loadWorkflowsSuccess']],
    })),
    actions({
        refreshWaitingWorkflows: true,
    }),
    selectors({
        hasWaitingWorkflows: [
            (s) => [s.workflows],
            (workflows: WorkflowsResult): boolean =>
                workflows.results.some(({ status }: HogFlow) => status === 'waiting_for_domain'),
        ],
    }),
    listeners(({ actions, values, cache }) => ({
        refreshWaitingWorkflows: async () => {
            if (values.workflowsLoading) {
                return
            }
            const shown = values.workflows
            const params = values.paramsFromFilters
            let response: WorkflowsResult
            try {
                response = await api.hogFlows.getHogFlows(params)
            } catch {
                return
            }
            const superseded =
                values.workflowsLoading || values.workflows !== shown || !objectsEqual(values.paramsFromFilters, params)
            if (cache.disposables.isDisposed || superseded) {
                return
            }
            // The success action, not the loader, so the table does not flash its loading state.
            actions.loadWorkflowsSuccess(response)
        },
    })),
    // The list changes through many loader actions, so follow the value rather than each action.
    subscriptions(({ actions, cache }) => ({
        hasWaitingWorkflows: (hasWaiting: boolean) => {
            syncWaitingStatusCheck(cache.disposables, hasWaiting, actions.refreshWaitingWorkflows)
        },
    })),
])
